const MINERALS = CATALOGUE.minerals;

function getPropertyProvenance(mineral, property) {
  const entry = CATALOGUE.provenanceProfiles[mineral.provenanceProfile]?.[property];
  if (!entry) return null;
  const [status, scope, origin, sourceIndex] = entry;
  return { status, scope, origin, source: mineral.sources[sourceIndex] ?? null };
}

function getDiagnosticReview(id) {
  return CATALOGUE.diagnosticReviews.find(review => review.alternatives.includes(id)) ?? null;
}
